import{_ as e,C as n,o as s,c as d,a2 as l,E as r}from"./chunks/framework.CDU0sSpB.js";const m=JSON.parse('{"title":"项目设计与取舍","description":"Hearth 的产品定位、核心取舍、系统架构、执行链路与完成标准。","frontmatter":{"title":"项目设计与取舍","description":"Hearth 的产品定位、核心取舍、系统架构、执行链路与完成标准。","outline":[2,3]},"headers":[],"relativePath":"design/index.md","filePath":"design/index.md","lastUpdated":1793797632000}'),i={name:"design/index.md"};function o(p,t,h,c,u,b){const a=n("DocCardGrid");return s(),d("div",null,[t[0]||(t[0]=l(`<p class="eyebrow">DESIGN</p><h1 id="从意图到可靠任务" tabindex="-1">从意图到可靠任务 <a class="header-anchor" href="#从意图到可靠任务" aria-label="Permalink to &quot;从意图到可靠任务&quot;">​</a></h1><p class="lead">Hearth 是一个单用户、自托管、长期驻留的个人 Agent OS。下面的内容把产品定位、关键取舍、系统架构和完成标准放在同一条叙事里：先说明为什么做，再说明怎么设计，最后说明怎样才算真的做成。</p><h2 id="先看结论" tabindex="-1">先看结论 <a class="header-anchor" href="#先看结论" aria-label="Permalink to &quot;先看结论&quot;">​</a></h2><blockquote><p><strong>Hearth 不追求“更会聊天”，而是让个人数字劳动变得持久、可控、可验证。</strong></p></blockquote><ul><li>用户面对的是任务、审批和产物，不是 Worker、Harness 或 Token 的内部细节。</li><li>系统持有任务状态、权限、预算、证据和恢复路径；模型只是可替换的执行能力之一。</li><li>能力按阶段增长，但每个阶段都必须交付可用的纵向切片，而不是只完成一层基础设施。</li></ul><h2 id="产品定位" tabindex="-1">产品定位 <a class="header-anchor" href="#产品定位" aria-label="Permalink to &quot;产品定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>定义</th></tr></thead><tbody><tr><td>用户</td><td>一个主要用户，可能有一到三个可信协作者</td></tr><tr><td>部署</td><td>本地优先、可自托管，个人文件和凭据默认留在自己的控制范围内</td></tr><tr><td>工作范围</td><td>研究、写作、文档、邮件、日程、代码、数据、网页和桌面操作的混合工作</td></tr><tr><td>首个楔子</td><td>选择一个高频、低外部风险、可验证的任务族先跑通完整闭环</td></tr><tr><td>产品形态</td><td>以任务卡、审批、产物和通知为核心，不以无限聊天记录为核心</td></tr><tr><td>明确不做</td><td>企业多租户、公开 Agent 市场、未审批的高风险自动化、基础模型竞赛</td></tr></tbody></table><h3 id="它不是什么" tabindex="-1">它不是什么 <a class="header-anchor" href="#它不是什么" aria-label="Permalink to &quot;它不是什么&quot;">​</a></h3><ul><li>不是另一个 Coding Agent；</li><li>不是只会转发提示词的 Codex 套壳；</li><li>不是把所有权限交给模型的黑盒；</li><li>不是需要用户每天维护提示词、插件和工作流的工具；</li><li>不是企业 IAM、组织审计和多租户平台。</li></ul><h2 id="核心取舍" tabindex="-1">核心取舍 <a class="header-anchor" href="#核心取舍" aria-label="Permalink to &quot;核心取舍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>取舍</th><th>Hearth 的选择</th><th>原因</th></tr></thead><tbody><tr><td>任务还是对话</td><td>以任务卡和完成证据为中心</td><td>长任务需要状态、预算、审批和恢复，聊天记录不是可靠事实源</td></tr><tr><td>状态放在哪里</td><td>Event Log 作为唯一事实源，界面只做投影</td><td>崩溃、换设备、重放和审计都需要同一条事实链</td></tr><tr><td>谁来执行</td><td>Native、Codex、Connector、Browser、GUI、Document/Data、Human 并列</td><td>不同任务需要不同能力、风险和 Token 成本，不能押注单一模型</td></tr><tr><td>自研还是集成</td><td>自研控制面、执行内核、记忆、验证和体验；集成模型、沙箱、浏览器和外部 API</td><td>控制、授权、证据和恢复是产品护城河，底层能力应复用成熟实现</td></tr><tr><td>副作用怎么处理</td><td>预览、审批、幂等键、outbox 和 Receipt</td><td>邮件、写入、分享、删除和桌面动作必须可追溯、可对账、可恢复</td></tr><tr><td>数据放在哪里</td><td>单用户、本地优先、可迁移</td><td>个人上下文、记忆和凭据不能默认离开用户控制</td></tr><tr><td>记忆和进化如何开放</td><td>记忆可解释、可纠正、可遗忘；技能必须评估、灰度、晋升和回滚</td><td>让系统积累经验，但不允许无边界自修改</td></tr><tr><td>如何推进交付</td><td>按能力门槛和纵向增量推进，不按日历承诺</td><td>先证明可靠，再扩大范围；每个阶段都能停留、试用和回退</td></tr></tbody></table><h2 id="一条执行链" tabindex="-1">一条执行链 <a class="header-anchor" href="#一条执行链" aria-label="Permalink to &quot;一条执行链&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户 / CLI / Web / Mobile / IM</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>     Experience Plane       任务卡 · 审批 · 产物 · 接管</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>     Personal Gateway       身份 · 渠道 · 设备 · 注意力入口</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      Control Plane         触发 · 策略 · 授权 · 调度 · 监管</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>     Durable Harness        任务图 · 预算 · lease · 重试 · 恢复</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      Executor Layer        Native · Codex · Connector · Browser</span></span>
<span class="line"><span>                            GUI · Document/Data · Human</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>    Execution Gateway       工作区 · Sandbox · 网络 · 凭据代理</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span> Event Log / Artifacts / Receipts</span></span>
<span class="line"><span>       ↓                    ↓</span></span>
<span class="line"><span>  Memory OS            Evolution OS</span></span></code></pre></div><p>任何事实都写入 Event Log；任何外部副作用都经过授权、幂等和回执；任何界面状态都从事件投影重建，而不是依赖内存中的临时对象。</p><h2 id="系统由哪些部分组成" tabindex="-1">系统由哪些部分组成 <a class="header-anchor" href="#系统由哪些部分组成" aria-label="Permalink to &quot;系统由哪些部分组成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平面</th><th>主要责任</th></tr></thead><tbody><tr><td>Experience Plane</td><td>任务卡、审批、产物、接管和通知</td></tr><tr><td>Personal Gateway</td><td>身份、渠道归一化、设备注册和注意力入口</td></tr><tr><td>Control Plane</td><td>意图判断、触发、策略、授权、调度和 Watchdog</td></tr><tr><td>Durable Harness</td><td>任务图、路由、预算、lease、重试和恢复</td></tr><tr><td>Executor Layer</td><td>用统一协议承载不同执行器和人工接管</td></tr><tr><td>Execution Gateway</td><td>工作区、Sandbox、网络、浏览器、GUI 和 Credential Broker</td></tr><tr><td>Memory / Evolution</td><td>个人上下文、记忆、技能、评估、晋升和回滚</td></tr></tbody></table><p>所有平面围绕 Event Log 协作。第一阶段采用模块化单体和单写者，不提前拆微服务；边界由接口、schema、事件和测试保证。</p><h2 id="任务覆盖与完成标准" tabindex="-1">任务覆盖与完成标准 <a class="header-anchor" href="#任务覆盖与完成标准" aria-label="Permalink to &quot;任务覆盖与完成标准&quot;">​</a></h2><p>Hearth 的任务范围包括沟通协作、文档内容、研究整理、代码研发、数据表格、网页 SaaS、桌面应用和个人事务。自主级别从 A0 建议、A1 受控执行、A2 授权执行到 A3 受监督自主，按任务族、来源、设备、金额和时间段分别配置。</p><p>“完成”不是模型说一句“已完成”，而是同时具备：</p><ul><li>用户可见的结果和下一步；</li><li>持久状态、验证器和可复现证据；</li><li>外部副作用对应的审批、幂等键和回执；</li><li>失败原因、恢复入口或明确的人工接管路径。</li></ul><p>完整任务覆盖和默认清单见<a href="/hearth-os/reference/">附录总览</a>与<a href="/hearth-os/reference/checklists.html">默认清单</a>。</p><h2 id="不可妥协的边界" tabindex="-1">不可妥协的边界 <a class="header-anchor" href="#不可妥协的边界" aria-label="Permalink to &quot;不可妥协的边界&quot;">​</a></h2><ol><li>Event Log 是唯一事实源。</li><li>每个状态根只有一个写权威。</li><li>所有外部副作用必须有幂等键、审批或明确豁免，以及 Receipt。</li><li>执行器不能直接读取长期原始凭据。</li><li>每个任务必须有预算、截止时间和取消路径。</li><li>记忆必须有来源、敏感度、冲突和遗忘策略。</li><li>技能变化必须经过评估、灰度、晋升和回滚。</li><li>每个增量都必须是完整纵向切片：用户结果、界面、持久状态、真实执行、验证和恢复同时出现。</li></ol><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><p>Hearth 目前处于规格与规划阶段。产品、架构、安全、评估和交付路线已经定义，可运行实现尚未开始；下一步是第一阶段：确定首个场景与真实任务，做出完整体验原型，并打通最小任务闭环。</p><h2 id="继续阅读" tabindex="-1">继续阅读 <a class="header-anchor" href="#继续阅读" aria-label="Permalink to &quot;继续阅读&quot;">​</a></h2>`,28)),r(a,{columns:3,items:[{no:"01",title:"系统架构细节",text:"从总体数据流、领域模型和持久执行进入实现层。",link:"/architecture/overview"},{no:"02",title:"交付路线",text:"查看六个阶段、24 个小阶段如何从 MVP 推进到长期运行。",link:"/delivery/"},{no:"03",title:"附录",text:"查阅工程边界、风险、ADR、术语、清单与完整归档。",link:"/reference/"}]})])}const k=e(i,[["render",o]]);export{m as __pageData,k as default};
